package main

import (
	"fmt"
	"net/http"
	"net/smtp"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
)

type ContactForm struct {
	Name    string `json:"name" binding:"required"`
	Email   string `json:"email" binding:"required"`
	Subject string `json:"subject" binding:"required"`
	Message string `json:"message" binding:"required"`
}

func sendNotification(form ContactForm) error {
	smtpHost := os.Getenv("SMTP_HOST")
	smtpPort := os.Getenv("SMTP_PORT")
	senderEmail := os.Getenv("SENDER_EMAIL")
	adminEmail := os.Getenv("ADMIN_EMAIL")
	smtpPassword := os.Getenv("SMTP_PASSWORD")

	// Build email headers manually for custom formatting
	headers := make(map[string]string)
	headers["From"] = senderEmail
	headers["To"] = adminEmail
	headers["Subject"] = fmt.Sprintf("Contact Form: %s", form.Subject)
	headers["Reply-To"] = form.Email
	headers["X-Contact-Name"] = form.Name
	headers["MIME-Version"] = "1.0"
	headers["Content-Type"] = "text/plain; charset=UTF-8"

	var msg strings.Builder
	for k, v := range headers {
		msg.WriteString(fmt.Sprintf("%s: %s\r\n", k, v))
	}
	msg.WriteString("\r\n")
	msg.WriteString(fmt.Sprintf("Name: %s\nEmail: %s\n\nMessage:\n%s", form.Name, form.Email, form.Message))

	auth := smtp.PlainAuth("", senderEmail, smtpPassword, smtpHost)
	err := smtp.SendMail(
		fmt.Sprintf("%s:%s", smtpHost, smtpPort),
		auth,
		senderEmail,
		[]string{adminEmail},
		[]byte(msg.String()),
	)
	return err
}

func logSubmissionToS3(form ContactForm) error {
	// Logs contact form submission metadata to S3 for audit
	// Uses AWS SDK with default credential chain
	bucket := os.Getenv("AUDIT_BUCKET")
	if bucket == "" {
		return fmt.Errorf("AUDIT_BUCKET not configured")
	}
	// Simplified: actual implementation uses aws-sdk-go
	// The S3 PutObject call goes through VPC endpoint
	fmt.Printf("Audit log written to s3://%s/contacts/%s\n", bucket, form.Email)
	return nil
}

func main() {
	r := gin.Default()

	r.POST("/api/contact", func(c *gin.Context) {
		var form ContactForm
		if err := c.ShouldBindJSON(&form); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid form data"})
			return
		}

		// Basic validation - check email format loosely
		if !strings.Contains(form.Email, "@") {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid email"})
			return
		}

		// Log to S3 audit bucket
		if err := logSubmissionToS3(form); err != nil {
			// Non-fatal: log but continue
			fmt.Printf("Audit log failed: %v\n", err)
		}

		if err := sendNotification(form); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to send message"})
			return
		}

		c.JSON(http.StatusOK, gin.H{"status": "Message sent successfully"})
	})

	r.Run(":8080")
}
